using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ShieldedCrossbowOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/ShieldedCrossbowOmenData", order = 0)]
public class ShieldedCrossbowOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.ShieldedCrossbowOmenAction = delegate(int effectAmount, GameObject target)
		{
			if (!(ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.EndOfBattleState) && target.GetComponent<CorruptionStats>() != null && (!(target.GetComponent<CorruptionStats>() is CompanionCorruptionStats) || (target.GetComponent<CorruptionStats>() as CompanionCorruptionStats).CompanionForBattle))
			{
				omenInstance.ActivateOmenFeedback();
				ActivateOmen(effectAmount, target);
			}
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.ShieldedCrossbowOmenAction = null;
	}
}
